//
// @example "Glob files"
// src/**/*.ts
// @example "Multiple targets — semicolon-delimited list"
// src/**/*.ts; test/**/*.ts
// @example "Glob gitignored files like .env"
// glob(path=".env*", gitignore=False)
// @example "Glob directories matching a name (returns both files and dirs; directories are suffixed with `/`)"
// **/tests
type glob = (_: {
// glob, file, or directory to search — a single path or a semicolon-delimited list ("src/**/*.ts; test/**/*.ts"). Omitted -> searches the workspace root (".")
path?: string,
// include hidden files
hidden?: boolean,
// respect gitignore
gitignore?: boolean,
// max results
limit?: number,
