      "type": "Concept",
      "description": "An error where students misread vertical axis values in bar charts (such as reading 3.75 as 3.5 or 4) due to inaccurate eye estimation."
    },
    {
      "name": "Perpendicular Ruler Technique",
      "type": "Method",
      "description": "A pedagogical remedial action where students place a ruler perpendicular to the vertical axis of a bar chart to accurately read values."
    },
    {
      "name": "Probability Denominator Error",
      "type": "Concept",
      "description": "A mathematical error where students confuse total trials with complementary outcomes, leading to writing incorrect probability denominators such as 6/14 instead of 6/20."
    },
    {
      "name": "Keyword Underlining And Explicit Total Computation",
      "type": "Method",
      "description": "A pedagogical intervention where students underline keywords in problem statements and explicitly compute the total number of outcomes (such as 6 + 14 = 20)."
    },
    {
      "name": "Fraction Reduction Failure",
      "type": "Concept",
      "description": "A student error involving the failure to simplify fractions, such as 6/20 or 6/14, to their lowest terms."
    },
    {
      "name": "Common Divisor Verification Habit",
      "type": "Method",
      "description": "A habit-building remedial practice where students systematically check for common divisors to reduce fractions to lowest terms."
    },
    {
      "name": "Decimal Addition Misalignment",
      "type": "Concept",
      "description": "An arithmetic error occurring during the addition of decimal numbers with differing decimal lengths, such as adding 3.25, 4.5, and 4 without proper alignment."
    },
    {
      "name": "Trailing Zero Padding",
      "type": "Method",
      "description": "A remedial procedure where trailing zeros are added to align decimal numbers of differing lengths before addition (such as 3.25 + 4.50 + 4.00)."
