    {
      "name": "Multiplying By 0.1 Misconception",
      "type": "Concept",
      "description": "A cognitive misconception regarding multiplication by 0.1, resulting in erroneous calculations like 37.5 \\times 0.1 = 375 or 0.375."
    },
    {
      "name": "Decimal Point Left Shift Rule",
      "type": "Method",
      "description": "A remedial instructional rule reinforcing that multiplying a number by 0.1 is equivalent to dividing by 10, which shifts the decimal point one place to the left (e.g., to 3.75)."
    },
