{
  "entities": [
    {
      "name": "Circle Circumference",
      "type": "Concept",
      "description": "A one-dimensional boundary length measurement of a circle calculated using the formula C = r * 2 * 3.14 and measured in linear units such as centimeters or meters."
    },
    {
      "name": "Circle Area",
      "type": "Concept",
      "description": "A two-dimensional planar magnitude measurement of a circle calculated using the formula S = r * r * 3.14 and measured in square units such as square centimeters or square meters."
    },
    {
      "name": "Radius",
      "type": "Concept",
      "description": "The geometric distance from the center of a circle to its boundary, denoted as r, equal to half of the diameter (r = d : 2)."
    },
    {
      "name": "Diameter",
      "type": "Concept",
      "description": "A straight line segment passing through the center of a circle and connecting two points on its boundary, denoted as d."
    },
    {
      "name": "Triangle Area",
      "type": "Concept",
      "description": "The two-dimensional surface measurement of a triangle, calculated by multiplying base by height and dividing by 2."
    },
    {
      "name": "Trapezoid Area",
      "type": "Concept",
      "description": "The two-dimensional surface measurement of a trapezoid, calculated from its bases and height with a required division by 2."
    },
    {
      "name": "Parallelogram Area",
      "type": "Concept",
      "description": "The two-dimensional surface measurement of a parallelogram calculated as base multiplied by height (a * h) without dividing by 2."
    },
    {
      "name": "Rectangle Area",
      "type": "Concept",
      "description": "The two-dimensional surface measurement of a rectangle calculated as length multiplied by width (a * b) without dividing by 2."
    },
    {
      "name": "Obtuse Angle",
      "type": "Concept",
      "description": "An angle measuring greater than 90 degrees that students frequently misidentify due to optical illusions or visual tilt of triangle edges."
    },
    {
      "name": "Set Square",
      "type": "Artifact",
      "description": "A triangular drawing tool (ê ke) used to verify whether an angle is greater than or less than 90 degrees by aligning one perpendicular side with the base."
    },
    {
      "name": "Triangle Classification",
      "type": "Method",
      "description": "The mathematical task of categorizing triangles based on their angle properties, such as identifying obtuse, acute, or right triangles."
    }
  ],
  "relationships": [
    {
      "source": "Circle Circumference",
      "target": "Circle Area",
      "keywords": "measurement confusion, geometric dimension, formula distinction",
      "description": "Circle Circumference and Circle Area are often confused by students regarding measurement units (1D vs 2D) and computation formulas due to shared variables."
    },
    {
      "source": "Circle Area",
      "target": "Radius",
      "keywords": "formula variable, geometric calculation",
      "description": "Circle Area is calculated using Radius multiplied by itself and 3.14 (S = r * r * 3.14)."
    },
    {
      "source": "Circle Circumference",
      "target": "Radius",
      "keywords": "formula variable, linear calculation",
      "description": "Circle Circumference is calculated by multiplying Radius by 2 and 3.14 (C = r * 2 * 3.14)."
    },
    {
      "source": "Radius",
      "target": "Diameter",
      "keywords": "geometric relation, division calculation",
      "description": "Radius is determined by dividing Diameter by 2 (r = d : 2), a prerequisite step to prevent formula errors in circle calculations."
    },
    {
      "source": "Circle Area",
      "target": "Diameter",
      "keywords": "calculation error, formula confusion",
      "description": "Students mistakenly compute Circle Area by multiplying Diameter directly by itself instead of converting it to Radius."
    },
    {
      "source": "Triangle Area",
      "target": "Parallelogram Area",
      "keywords": "geometric relation, geometric composition, formula derivation",
      "description": "Triangle Area requires division by 2 because two identical triangles combine to form a corresponding parallelogram."
    },
    {
      "source": "Trapezoid Area",
      "target": "Parallelogram Area",
      "keywords": "geometric relation, geometric composition, division by two",
      "description": "Trapezoid Area requires division by 2 because two identical trapezoids combine to form a corresponding parallelogram."
    },
    {
      "source": "Triangle Area",
      "target": "Rectangle Area",
      "keywords": "formula interference, cognitive confusion",
      "description": "Familiarity with Rectangle Area calculation often causes students to omit the division by 2 when computing Triangle Area."
    },
    {
      "source": "Obtuse Angle",
      "target": "Set Square",
      "keywords": "measurement tool, angle verification, pedagogical remedy",
      "description": "A Set Square is used to physically determine and verify if an angle is an Obtuse Angle by testing if it exceeds 90 degrees."
    },
    {
      "source": "Obtuse Angle",
      "target": "Triangle Classification",
      "keywords": "classification error, geometric categorization",
      "description": "Correctly identifying an Obtuse Angle is essential for accurate Triangle Classification, where visual illusions often lead to misclassification."
    }
  ]
}

